import{at as e,it as t,n,vt as r}from"./chunks/framework.BPeR9Rpo.js";var i=JSON.parse(`{"title":"Change history","description":"","frontmatter":{"title":"Change history","covers":{"screens":["SCR-026"],"stories":["US-098","US-099","US-100"]}},"headers":[],"relativePath":"usage/change-history.md","filePath":"usage/change-history.md"}`),a={name:`usage/change-history.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="change-history" tabindex="-1">Change history <a class="header-anchor" href="#change-history" aria-label="Permalink to “Change history”">​</a></h1><p>Every change to an entity creates a new version. The page <em>Change history</em> shows who changed an entity when, which fields each version changed, and the values before and after. You need the permission <code>entity:read</code>; the roles <code>viewer</code>, <code>analyst</code> and <code>enterprise-architect</code> have it.</p><h2 id="open-the-change-history" tabindex="-1">Open the change history <a class="header-anchor" href="#open-the-change-history" aria-label="Permalink to “Open the change history”">​</a></h2><p>In a <a href="./catalogs">catalog</a> or in a catalog of the <a href="./portal">portal</a>, choose <em>History</em> in the row of an entity. The page opens with the versions of the entity, newest first. <em>Back to the catalog</em> returns to the catalog you came from, on the same page and with the same sort.</p><h2 id="read-the-entries" tabindex="-1">Read the entries <a class="header-anchor" href="#read-the-entries" aria-label="Permalink to “Read the entries”">​</a></h2><p>Each entry shows:</p><ul><li>the <strong>version number</strong>, with <em>Created</em> for the first version;</li><li>the <strong>time</strong> of the change in your local time zone;</li><li>the <strong>person</strong> who made the change;</li><li>the <strong>changed fields</strong>: system fields such as <em>Name</em> or <em>Description</em>, and the properties by their label.</li></ul><p>The entries name the changed fields. Their values appear when you open a version.</p><p>An entity that was never changed after its creation shows <em>No changes since creation. Created on {date} by {person}.</em></p><h2 id="see-the-values-of-a-version" tabindex="-1">See the values of a version <a class="header-anchor" href="#see-the-values-of-a-version" aria-label="Permalink to “See the values of a version”">​</a></h2><p>Choose <em>Show changes</em> in an entry. It lists each changed field with its old value in red and struck through, and its new value in green; a field without value shows <em>—</em>. Only fields whose value differs are listed. <em>Created</em> has no changes to show.</p><p><em>Show complete state vN</em> lists every field of the entity as it was at that version: the system fields and the properties of its entity type, including empty ones. The properties are those assigned to the entity type at the time of the version. If a package import later removed an assignment, an empty property of that assignment is missing from older states; a property that had a value then is always listed.</p><p>Versions cannot be changed or deleted.</p><h2 id="compare-two-versions" tabindex="-1">Compare two versions <a class="header-anchor" href="#compare-two-versions" aria-label="Permalink to “Compare two versions”">​</a></h2><p>Choose <em>Compare</em>, then select two versions. A panel above the timeline shows the fields whose value differs between the earlier and the later version. A field that was changed and later changed back does not appear. Selecting a third version replaces the version you selected first. <em>End comparison</em> closes the panel.</p><h2 id="restricted-fields" tabindex="-1">Restricted fields <a class="header-anchor" href="#restricted-fields" aria-label="Permalink to “Restricted fields”">​</a></h2><p>A property you may not read under the <a href="./../administration/property-visibility">property visibility</a> never shows its value, neither in the changes nor in the complete state. Depending on the settings of your roles for the entity type, the field appears with the badge <em>Restricted</em>, or it is left out. If all fields of a version are left out, the version stays in the list without fields, so that the numbering has no gaps.</p><h2 id="filter-and-load-more" tabindex="-1">Filter and load more <a class="header-anchor" href="#filter-and-load-more" aria-label="Permalink to “Filter and load more”">​</a></h2><ul><li><strong>Person:</strong> choose a person to see only the versions they made. The list offers everyone who changed the entity.</li><li><strong>Period:</strong> choose a start and an end date. Both days count fully: a version on the start or the end date is shown.</li></ul><p>The page shows 50 versions at first. <em>Load more</em> adds the next 50.</p><h2 id="through-the-api" tabindex="-1">Through the API <a class="header-anchor" href="#through-the-api" aria-label="Permalink to “Through the API”">​</a></h2><p><code>GET /entities/{id}/history</code> returns the versions newest first, with <code>from</code> and <code>to</code> (inclusive timestamps), <code>actorId</code>, <code>page</code>, <code>pageSize</code> (1 to 200, default 50) and <code>cursor</code> (the <code>nextCursor</code> of the previous page, sent with <code>page</code> + 1). The answer names the creation in <code>created</code> and every person who made a version in <code>actors</code>, independent of the filters. A start after the end answers 400 naming <code>from</code>, an unknown entity 404.</p><p><code>GET /entities/{id}/versions/{version}</code> returns the complete state of a version in <code>fields</code>, each with <code>field</code>, <code>label</code>, <code>dataType</code>, <code>value</code> and <code>restricted</code>. <code>GET /entities/{id}/diff?from=2&amp;to=7</code> returns the fields whose value differs between two versions in <code>changes</code>, each with <code>oldValue</code>, <code>newValue</code> and <code>redacted</code>; the changes of version N are <code>from=N-1&amp;to=N</code>. <code>from</code> must be at least 1 and before <code>to</code>, otherwise 400 naming <code>from</code>; an unknown version answers 404. <code>PUT</code> and <code>DELETE</code> on a version answer 405.</p>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};